def note_duration(length):
    if "/" in length:
        n, d = length.split("/")
        value = int(n) / int(d)
    else:
        value = int(length)

    return BEAT * value * 4


def play_note(note, length):
    duration = note_duration(length)

    if note is None:
        buzzer.duty_u16(0)
        sleep(duration)
        return

    if note not in NOTES:
        print("Unknown note:", note)
        return

    buzzer.freq(NOTES[note])
    buzzer.duty_u16(32768)
    sleep(duration)
    buzzer.duty_u16(0)


def play_song(song):
    for note, length in song:
        play_note(note, length)
        sleep(0.01)

